import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import {
    Alert, Autocomplete, Box, Button, Chip, Container, Grid, Paper, Stack, TextField, Typography,
} from '@mui/material';
import MyLocationIcon from '@mui/icons-material/MyLocation';
import ExploreIcon from '@mui/icons-material/Explore';
import apiConfig from '../config/apiConfig';
import qiblaCities from '../config/qiblaCities.json';

// The Qibla page (2026-10-27). Direction comes from GET /v1/qibla/:lat/:lng;
// the same great-circle formula runs here as a fallback, so the page still
// answers when the API is unreachable.

const KAABA = { latitude: 21.4225241, longitude: 39.8261818 };
const GOLD = '#d4af37';
const POINTS = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
const rad = (d) => (d * Math.PI) / 180;

function localQibla(latitude, longitude) {
    const dLong = rad(KAABA.longitude) - rad(longitude);
    const angle = Math.atan2(
        Math.sin(dLong),
        Math.cos(rad(latitude)) * Math.tan(rad(KAABA.latitude)) - Math.sin(rad(latitude)) * Math.cos(dLong),
    ) * 180 / Math.PI;
    const direction = ((angle % 360) + 360) % 360;
    const dLat = rad(KAABA.latitude - latitude);
    const a = Math.sin(dLat / 2) ** 2
        + Math.cos(rad(latitude)) * Math.cos(rad(KAABA.latitude)) * Math.sin(dLong / 2) ** 2;
    const distanceKm = Math.round(6371.0088 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)) * 10) / 10;
    return { latitude, longitude, direction, compassPoint: POINTS[Math.round(direction / 22.5) % 16], distanceKm };
}

async function fetchQibla(latitude, longitude) {
    try {
        const res = await fetch(`${apiConfig.baseUrl}/qibla/${latitude}/${longitude}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return (await res.json()).data;
    } catch (e) {
        return localQibla(latitude, longitude);
    }
}

const CITY_OPTIONS = qiblaCities.cities.map(([name, region, country, lat, lon]) => ({
    label: region && region !== name ? `${name}, ${region}, ${country}` : `${name}, ${country}`,
    latitude: lat,
    longitude: lon,
}));

const FAMOUS = [
    ['New York', 40.7128, -74.006], ['London', 51.5074, -0.1278], ['Toronto', 43.6535, -79.3839],
    ['Karachi', 24.8607, 67.0011], ['Jakarta', -6.2088, 106.8456], ['Istanbul', 41.0082, 28.9784],
    ['Cairo', 30.0444, 31.2357], ['Kuala Lumpur', 3.139, 101.6869], ['Lagos', 6.5244, 3.3792],
    ['Sydney', -33.8688, 151.2093], ['Dubai', 25.2048, 55.2708], ['Los Angeles', 34.0522, -118.2437],
].map(([name, lat, lon]) => ({ name, latitude: lat, longitude: lon, ...localQibla(lat, lon) }));

// Live phone compass: degrees from north, or null when the device has none.
function useDeviceHeading() {
    const [heading, setHeading] = useState(null);
    const [needsPermission, setNeedsPermission] = useState(
        typeof window !== 'undefined' && typeof window.DeviceOrientationEvent?.requestPermission === 'function',
    );
    const handler = useRef((e) => {
        if (typeof e.webkitCompassHeading === 'number') setHeading(e.webkitCompassHeading);
        else if (e.absolute && typeof e.alpha === 'number') setHeading((360 - e.alpha) % 360);
    });
    const listen = useCallback(() => {
        window.addEventListener('deviceorientationabsolute', handler.current, true);
        window.addEventListener('deviceorientation', handler.current, true);
    }, []);
    useEffect(() => {
        if (!needsPermission && typeof window !== 'undefined' && 'DeviceOrientationEvent' in window) listen();
        const h = handler.current;
        return () => {
            window.removeEventListener('deviceorientationabsolute', h, true);
            window.removeEventListener('deviceorientation', h, true);
        };
    }, [needsPermission, listen]);
    const requestPermission = useCallback(async () => {
        try {
            if (await window.DeviceOrientationEvent.requestPermission() === 'granted') {
                setNeedsPermission(false);
                listen();
            }
        } catch (e) { /* the user said no */ }
    }, [listen]);
    return { heading, needsPermission, requestPermission };
}

function Dial({ direction, heading }) {
    // With a live compass the dial turns so the arrow points at the real Qibla.
    const dialTurn = heading == null ? 0 : -heading;
    const aligned = heading != null && Math.abs(((direction - heading + 540) % 360) - 180) < 4;
    const ticks = Array.from({ length: 72 }, (_, i) => i * 5);
    return (
        <Box sx={{ position: 'relative', width: 'min(84vw, 380px)', aspectRatio: '1', mx: 'auto' }}>
            <Box sx={{
                position: 'absolute', inset: '-8%', borderRadius: '50%',
                background: `radial-gradient(circle, ${aligned ? 'rgba(212,175,55,.45)' : 'rgba(212,175,55,.18)'} 0%, transparent 65%)`,
                transition: 'background .4s',
                animation: 'qiblaPulse 4s ease-in-out infinite',
                '@keyframes qiblaPulse': { '0%,100%': { opacity: 0.7 }, '50%': { opacity: 1 } },
            }} />
            <svg viewBox="-200 -200 400 400" width="100%" height="100%" role="img"
                aria-label={`Qibla is ${direction.toFixed(1)} degrees from true north`}
                style={{ transform: `rotate(${dialTurn}deg)`, transition: 'transform .25s ease-out', position: 'relative' }}>
                <defs>
                    <radialGradient id="dialFace" cx="50%" cy="40%">
                        <stop offset="0%" stopColor="#123f2c" />
                        <stop offset="100%" stopColor="#04140d" />
                    </radialGradient>
                    <linearGradient id="needle" x1="0" y1="1" x2="0" y2="0">
                        <stop offset="0%" stopColor="#8a6d1d" />
                        <stop offset="100%" stopColor="#f6dd8a" />
                    </linearGradient>
                </defs>
                <circle r="190" fill="url(#dialFace)" stroke={GOLD} strokeWidth="3" />
                <circle r="172" fill="none" stroke="rgba(212,175,55,.35)" strokeWidth="1" />
                {/* Eight-point star, the Rub el Hizb, in the centre */}
                <g opacity=".18" stroke={GOLD} fill="none" strokeWidth="2">
                    <rect x="-70" y="-70" width="140" height="140" />
                    <rect x="-70" y="-70" width="140" height="140" transform="rotate(45)" />
                </g>
                {ticks.map((t) => (
                    <line key={t} x1="0" y1={-190} x2="0" y2={t % 45 === 0 ? -168 : -180}
                        stroke={t % 90 === 0 ? GOLD : 'rgba(255,255,255,.45)'} strokeWidth={t % 45 === 0 ? 3 : 1}
                        transform={`rotate(${t})`} />
                ))}
                {['N', 'E', 'S', 'W'].map((p, i) => (
                    <text key={p} x={[0, 140, 0, -140][i]} y={[-140, 0, 140, 0][i]} dominantBaseline="central" textAnchor="middle"
                        fill={p === 'N' ? '#ff8a80' : '#f5f5f5'} fontSize="24" fontWeight="700"
                        fontFamily="Georgia, serif">{p}</text>
                ))}
                <g transform={`rotate(${direction})`} style={{ transition: 'transform 1s cubic-bezier(.2,.8,.2,1)' }}>
                    <path d="M0,-150 L14,10 L0,-4 L-14,10 Z" fill="url(#needle)" stroke="#5c4810" strokeWidth="1" />
                    {/* The Kaaba at the tip */}
                    <g transform="translate(0,-168)">
                        <rect x="-13" y="-13" width="26" height="26" rx="2" fill="#111" stroke={GOLD} strokeWidth="2" />
                        <rect x="-13" y="-6" width="26" height="4" fill={GOLD} />
                    </g>
                </g>
                <circle r="9" fill={GOLD} stroke="#5c4810" strokeWidth="2" />
            </svg>
            {aligned && (
                <Chip label="You are facing the Qibla" sx={{
                    position: 'absolute', bottom: -12, left: '50%', transform: 'translateX(-50%)',
                    bgcolor: GOLD, color: '#1a1a1a', fontWeight: 700,
                }} />
            )}
        </Box>
    );
}

const panel = {
    p: { xs: 2.5, md: 3 }, borderRadius: 3, color: '#f5f5f5',
    background: 'rgba(8, 30, 21, .72)', border: '1px solid rgba(212,175,55,.3)', backdropFilter: 'blur(6px)',
};

export default function QiblaPage() {
    const [place, setPlace] = useState(null);
    const [qibla, setQibla] = useState(null);
    const [locating, setLocating] = useState(false);
    const [error, setError] = useState('');
    const { heading, needsPermission, requestPermission } = useDeviceHeading();
    const alignedRef = useRef(false);

    const choose = useCallback(async (latitude, longitude, label) => {
        setError('');
        setPlace(label);
        setQibla(await fetchQibla(Number(latitude.toFixed(4)), Number(longitude.toFixed(4))));
    }, []);

    const locate = useCallback(() => {
        if (!navigator.geolocation) { setError('Your browser cannot share its location. Search for your city instead.'); return; }
        setLocating(true);
        navigator.geolocation.getCurrentPosition(
            (pos) => { setLocating(false); choose(pos.coords.latitude, pos.coords.longitude, 'Your location'); },
            () => { setLocating(false); setError('Location was not shared. Search for your city instead.'); },
            { enableHighAccuracy: true, timeout: 15000 },
        );
    }, [choose]);

    // Start with New York so the dial is never empty.
    useEffect(() => { choose(40.7128, -74.006, 'New York, United States'); }, [choose]);

    // A short buzz when the phone comes round to the Qibla.
    const aligned = qibla && heading != null && Math.abs(((qibla.direction - heading + 540) % 360) - 180) < 4;
    useEffect(() => {
        if (aligned && !alignedRef.current && navigator.vibrate) navigator.vibrate(60);
        alignedRef.current = Boolean(aligned);
    }, [aligned]);

    const miles = useMemo(() => qibla && Math.round(qibla.distanceKm * 0.621371), [qibla]);

    return (
        <Box sx={{
            mx: { xs: -2, sm: -3 }, mt: -4, mb: -4, borderRadius: { xs: 0, md: 4 }, py: { xs: 4, md: 7 }, minHeight: '100vh', position: 'relative', overflow: 'hidden',
            background: 'radial-gradient(ellipse at 50% 0%, #0f4a33 0%, #062016 45%, #020a07 100%)',
            '&::before': {
                content: '""', position: 'absolute', inset: 0, opacity: 0.6, pointerEvents: 'none',
                backgroundImage: 'radial-gradient(1px 1px at 20% 30%, #fff, transparent), radial-gradient(1px 1px at 70% 20%, #fff, transparent), radial-gradient(1.5px 1.5px at 40% 70%, #f6dd8a, transparent), radial-gradient(1px 1px at 85% 60%, #fff, transparent), radial-gradient(1px 1px at 10% 85%, #fff, transparent), radial-gradient(1.5px 1.5px at 55% 45%, #fff, transparent), radial-gradient(1px 1px at 92% 90%, #f6dd8a, transparent)',
                backgroundSize: '320px 320px',
            },
        }}>
            <Helmet>
                <title>Qibla Direction Finder - Find the Qibla from Anywhere | iMuslim Life</title>
                <meta name="description" content="Find the exact Qibla direction to the Kaaba in Makkah from your location or any city, with a live phone compass, degrees from true north and distance. Free and ad-free." />
            </Helmet>
            <Container maxWidth="lg" sx={{ position: 'relative' }}>
                <Stack alignItems="center" textAlign="center" spacing={1} sx={{ mb: 4, color: '#f5f5f5' }}>
                    <Typography sx={{ fontFamily: '"Amiri", "Scheherazade New", serif', fontSize: { xs: 34, md: 44 }, color: GOLD }} lang="ar" dir="rtl">
                        فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ
                    </Typography>
                    <Typography variant="body2" sx={{ opacity: 0.8, fontStyle: 'italic' }}>
                        “So turn your face toward al-Masjid al-Haram.” — Qur’an 2:144
                    </Typography>
                    <Typography variant="h3" component="h1" sx={{ fontWeight: 700, fontSize: { xs: 32, md: 46 }, pt: 2 }}>
                        Qibla Direction Finder
                    </Typography>
                    <Typography sx={{ maxWidth: 640, opacity: 0.85 }}>
                        Find the direction of the Kaaba in Makkah from wherever you are, measured from true north along the shortest path on the globe.
                    </Typography>
                </Stack>

                <Grid container spacing={4} alignItems="center">
                    <Grid item xs={12} md={6}>
                        {qibla && <Dial direction={qibla.direction} heading={heading} />}
                    </Grid>
                    <Grid item xs={12} md={6}>
                        <Paper elevation={0} sx={panel}>
                            <Stack spacing={2}>
                                <Button variant="contained" size="large" startIcon={<MyLocationIcon />} onClick={locate} disabled={locating}
                                    sx={{ '&&': { background: GOLD, color: '#1a1a1a', fontWeight: 700 }, '&&:hover': { background: '#e6c65a' } }}>
                                    {locating ? 'Finding you…' : 'Use my location'}
                                </Button>
                                <Autocomplete
                                    options={CITY_OPTIONS}
                                    onChange={(e, v) => v && choose(v.latitude, v.longitude, v.label)}
                                    filterOptions={(opts, { inputValue }) => {
                                        const q = inputValue.trim().toLowerCase();
                                        return q ? opts.filter((o) => o.label.toLowerCase().includes(q)).slice(0, 30) : opts.slice(0, 30);
                                    }}
                                    renderInput={(params) => (
                                        <TextField {...params} placeholder="…or search a city" sx={{
                                            '& .MuiOutlinedInput-root': { color: '#f5f5f5', bgcolor: 'rgba(255,255,255,.06)' },
                                            '& fieldset': { borderColor: 'rgba(212,175,55,.4)' },
                                        }} />
                                    )}
                                />
                                {error && <Alert severity="info">{error}</Alert>}
                                {qibla && (
                                    <Box>
                                        <Typography variant="overline" sx={{ color: GOLD, letterSpacing: 2 }}>{place}</Typography>
                                        <Typography sx={{ fontSize: { xs: 52, md: 64 }, fontWeight: 700, lineHeight: 1.1 }}>
                                            {qibla.direction.toFixed(1)}°
                                            <Typography component="span" sx={{ fontSize: 24, ml: 1.5, color: GOLD }}>{qibla.compassPoint}</Typography>
                                        </Typography>
                                        <Typography sx={{ opacity: 0.85 }}>clockwise from true north</Typography>
                                        <Typography sx={{ mt: 1.5 }}>
                                            The Kaaba is <b>{qibla.distanceKm.toLocaleString()} km</b> ({miles.toLocaleString()} miles) away.
                                        </Typography>
                                    </Box>
                                )}
                                {needsPermission && (
                                    <Button variant="outlined" startIcon={<ExploreIcon />} onClick={requestPermission}
                                        sx={{ color: GOLD, borderColor: GOLD }}>
                                        Turn on the live compass
                                    </Button>
                                )}
                                {heading != null && (
                                    <Typography variant="body2" sx={{ opacity: 0.8 }}>
                                        Live compass on: hold your phone flat and turn until the Kaaba is at the top.
                                    </Typography>
                                )}
                            </Stack>
                        </Paper>
                    </Grid>
                </Grid>

                <Grid container spacing={3} sx={{ mt: 5 }}>
                    <Grid item xs={12} md={6}>
                        <Paper elevation={0} sx={{ ...panel, height: '100%' }}>
                            <Typography variant="h5" component="h2" sx={{ color: GOLD, mb: 1.5 }}>How to use it</Typography>
                            <Box component="ol" sx={{ pl: 2.5, m: 0, '& li': { mb: 1 } }}>
                                <li>On a phone, lay it flat and away from metal, magnets and speakers.</li>
                                <li>Calibrate the compass if asked: move the phone in a figure of eight.</li>
                                <li>Turn yourself until the gold Kaaba on the dial points straight ahead.</li>
                                <li>On a computer, use the degrees with any compass. The angle is from <b>true</b> north, not magnetic north.</li>
                                <li>No compass? Check against a landmark: the sun sets roughly in the west.</li>
                            </Box>
                        </Paper>
                    </Grid>
                    <Grid item xs={12} md={6}>
                        <Paper elevation={0} sx={{ ...panel, height: '100%' }}>
                            <Typography variant="h5" component="h2" sx={{ color: GOLD, mb: 1.5 }}>Why does North America face north-east?</Typography>
                            <Typography sx={{ opacity: 0.9, mb: 1.5 }}>
                                The Earth is round, so the shortest path to Makkah is a great circle. On a flat map
                                Makkah looks south-east of New York, but the shortest path heads north-east, over the Atlantic.
                                This is the method most scholars use today, and the one the Fiqh Council of North America
                                has endorsed.
                            </Typography>
                            <Typography sx={{ opacity: 0.9 }}>
                                The Kaaba is at {KAABA.latitude.toFixed(4)}° N, {KAABA.longitude.toFixed(4)}° E. Small differences of a
                                degree or two are well within what scholars accept when facing the Qibla.
                            </Typography>
                        </Paper>
                    </Grid>
                </Grid>

                <Paper elevation={0} sx={{ ...panel, mt: 3 }}>
                    <Typography variant="h5" component="h2" sx={{ color: GOLD, mb: 2 }}>Qibla direction from major cities</Typography>
                    <Grid container spacing={1.5}>
                        {FAMOUS.map((c) => (
                            <Grid item xs={6} sm={4} md={3} key={c.name}>
                                <Box component="button" type="button" onClick={() => choose(c.latitude, c.longitude, c.name)} sx={{
                                    width: '100%', textAlign: 'left', cursor: 'pointer', p: 1.5, borderRadius: 2, color: 'inherit', font: 'inherit',
                                    bgcolor: 'rgba(255,255,255,.04)', border: '1px solid rgba(212,175,55,.2)',
                                    '&:hover': { borderColor: GOLD, bgcolor: 'rgba(212,175,55,.08)' },
                                }}>
                                    <Typography sx={{ fontWeight: 600 }}>{c.name}</Typography>
                                    <Typography variant="body2" sx={{ color: GOLD }}>{c.direction.toFixed(1)}° {c.compassPoint}</Typography>
                                </Box>
                            </Grid>
                        ))}
                    </Grid>
                </Paper>

                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} justifyContent="center" sx={{ mt: 5 }}>
                    <Button component={RouterLink} to="/prayer-times" variant="outlined" sx={{ color: GOLD, borderColor: GOLD }}>Prayer times for your city</Button>
                    <Button component={RouterLink} to="/alexa-skill" variant="outlined" sx={{ color: GOLD, borderColor: GOLD }}>Athan on Alexa</Button>
                    <Button component={RouterLink} to="/api" variant="outlined" sx={{ color: GOLD, borderColor: GOLD }}>Free Qibla API</Button>
                </Stack>
            </Container>
        </Box>
    );
}
